namespace LlamaCpp {

/*!
 * Connects the chat tools to MCP servers.
 *
 * Supports the MCP server built into Qt Creator (the "mcpserver" plugin,
 * which exposes the IDE itself – building, running, opening and
 * inspecting projects – as MCP tools) in addition to arbitrary
 * user-configured servers (managed on the "Tools" settings page, stored
 * in the McpServers setting as Tools::McpServerConfig entries).
 *
 * The bridge watches Core::McpManager for the builtin server's URL, keeps
 * an McpClient per server and publishes their tools through the
 * ToolFactory (as a remote tool provider), so the rest of llama.qtcreator
 * treats them exactly like local tools.
 *
 * Tool names must be unique across servers: when two servers expose the
 * same tool name, the earlier server wins (the builtin server first, then
 * the configured servers in their stored order).
 */
class McpBridge : public QObject, public RemoteToolProvider
{
    Q_OBJECT
public:
    //! Connection state of one server, for display on the settings page.
    struct ServerStatus
    {
        QString name;
        QUrl url;
        bool connected = false;
    };

    static McpBridge &instance();

    //! Display name of the builtin Qt Creator MCP server (its tool group
    //! name); reserved – configured servers must not use it.
    static QString builtInServerName();

    /*! Starts watching for the builtin Qt Creator MCP server and connects
        the configured servers. Safe to call multiple times. */
    void start();

    // RemoteToolProvider
    QStringList toolNames() const override;
    std::unique_ptr<Tool> createTool(const QString &name) const override;

    bool isMcpTool(const QString &name) const;
    //! Display name of the server that serves the tool, empty if none.
    QString serverForTool(const QString &name) const;
    Tools::McpToolInfo toolInfo(const QString &name) const;

    //! Identifies an in-flight tool call, for cancelToolCall().
    struct ToolCallHandle
    {
        QPointer<Tools::McpClient> client; // null once the client is gone
        quint32 requestId = 0;             // 0: no call in flight
    };

    /*! Forwards a tool call to the server that serves it. The returned
        handle is empty when \a callback was already invoked synchronously
        (no server serves the tool, or it is unavailable). */
    ToolCallHandle callTool(const QString &name,
                            const QJsonObject &arguments,
                            std::function<void(const QString &output, bool ok)> callback);

    /*! Aborts the call identified by \a handle; its callback is invoked
        with \a reason and ok=false unless it already finished. */
    static void cancelToolCall(const ToolCallHandle &handle, const QString &reason);

    /*! All servers (builtin first, then the configured ones in stored
        order) with their current connection state. */
    QList<ServerStatus> serverStatuses() const;

signals:
    void toolsChanged();
    void connectionChanged();

private:
    struct Server
    {
        QString name;
        Tools::McpClient *client = nullptr;
    };

    explicit McpBridge();

    const Server *findServerForTool(const QString &name) const;
    void syncServers();
    void onBuiltInServersChanged();
    QPair<QUrl, QStringList> builtInServerConnection() const;

    QVector<Server> m_servers; // builtin server first, then the configured ones
    QUrl m_builtInUrl;
    QStringList m_builtInHeaders;
    bool m_builtInActive = false;
    bool m_started = false;
};

} // namespace LlamaCpp

#include "mcpbridge.h"

#include "llamatr.h"
#include "llamasettings.h"
#include "mcptool.h"
#include "mcpserverconfig.h"

#include <coreplugin/mcp/mcpmanager.h>

#include <algorithm>

namespace LlamaCpp {

// ID under which the builtin MCP server plugin registers itself with
// Core::McpManager (see the "mcpserver" plugin of Qt Creator).
static const char kQtCreatorMcpServerId[] = "QTCREATOR.BUILTIN.MCP.SERVER";

// Display name of the builtin server (also its tool group name).
static const char kBuiltInServerName[] = "Qt Creator";

McpBridge &McpBridge::instance()
{
    // Intentionally leaked: a QObject singleton that is destroyed during the
    // static-destruction phase at exit (after the QCoreApplication and the
    // Core::McpManager it talks to are already gone) leads to
    // use‑after‑free.
    static McpBridge *inst = new McpBridge;
    return *inst;
}

McpBridge::McpBridge()
    : QObject(nullptr)
{
}

QString McpBridge::builtInServerName()
{
    return QString::fromUtf8(kBuiltInServerName);
}

void McpBridge::start()
{
    if (m_started)
        return;
    m_started = true;

    connect(&Core::McpManager::instance(),
            &Core::McpManager::mcpServersChanged,
            this,
            &McpBridge::onBuiltInServersChanged);
    // The tools settings page adds / edits / removes configured servers;
    // pick that up without a restart.
    connect(&settings(),
            &LlamaSettings::subAspectChanged,
            this,
            [this](Utils::BaseAspect *aspect) {
                if (aspect == static_cast<Utils::BaseAspect *>(&settings().mcpServersJson))
                    syncServers();
            });

    onBuiltInServersChanged();
}

QStringList McpBridge::toolNames() const
{
    QStringList names;
    QSet<QString> seen;
    for (const Server &server : m_servers) {
        for (const Tools::McpToolInfo &info : server.client->tools()) {
            // Tool names must be unique across servers; the earlier server
            // (in priority order) wins.
            if (seen.contains(info.name))
                continue;
            seen.insert(info.name);
            names << info.name;
        }
    }
    return names;
}

std::unique_ptr<Tool> McpBridge::createTool(const QString &name) const
{
    if (!findServerForTool(name))
        return nullptr;
    return std::make_unique<Tools::McpTool>(name);
}

const McpBridge::Server *McpBridge::findServerForTool(const QString &name) const
{
    for (const Server &server : m_servers)
        if (server.client && server.client->isToolKnown(name))
            return &server;
    return nullptr;
}

bool McpBridge::isMcpTool(const QString &name) const
{
    return findServerForTool(name) != nullptr;
}

QString McpBridge::serverForTool(const QString &name) const
{
    const Server *server = findServerForTool(name);
    return server ? server->name : QString();
}

Tools::McpToolInfo McpBridge::toolInfo(const QString &name) const
{
    const Server *server = findServerForTool(name);
    return server ? server->client->toolInfo(name) : Tools::McpToolInfo{};
}

McpBridge::ToolCallHandle McpBridge::callTool(
    const QString &name,
    const QJsonObject &arguments,
    std::function<void(const QString &output, bool ok)> callback)
{
    const Server *server = findServerForTool(name);
    if (!server) {
        callback(Tr::tr("The MCP tool \"%1\" is not available (no connected MCP "
                        "server serves it).")
                       .arg(name),
                 false);
        return {};
    }
    // The call mutates only the client's own state (pending calls, …), not
    // the bridge's server list, so the const-ness can be dropped there.
    Tools::McpClient *client = const_cast<Tools::McpClient *>(server->client);
    const quint32 requestId = client->callTool(name, arguments, std::move(callback));
    if (requestId == 0)
        return {};
    return {client, requestId};
}

void McpBridge::cancelToolCall(const ToolCallHandle &handle, const QString &reason)
{
    // A client removed from the bridge has already failed its pending
    // calls (disconnectFromServer()) before being deleted.
    if (handle.client && handle.requestId != 0)
        handle.client->cancelToolCall(handle.requestId, reason);
}

QList<McpBridge::ServerStatus> McpBridge::serverStatuses() const
{
    QList<ServerStatus> result;
    result.reserve(m_servers.size());
    for (const Server &server : m_servers) {
        ServerStatus status;
        status.name = server.name;
        status.connected = server.client->isConnected();
        status.url = server.name == QLatin1String(kBuiltInServerName) ? m_builtInUrl
                                                                      : server.client->url();
        result.append(status);
    }
    return result;
}

QPair<QUrl, QStringList> McpBridge::builtInServerConnection() const
{
    const QList<Core::McpManager::ServerInfo> servers = Core::McpManager::mcpServers();
    for (const Core::McpManager::ServerInfo &info : servers) {
        if (info.id != QLatin1String(kQtCreatorMcpServerId))
            continue;
        if (const QUrl *url = std::get_if<QUrl>(&info.launchInfo))
            // httpHeaders carries the server's authentication header ("Authorization: Bearer …")
            // when token auth is enabled, empty otherwise.
            return {*url, info.httpHeaders};
        return {};
    }
    return {};
}

void McpBridge::onBuiltInServersChanged()
{
    const auto [url, headers] = builtInServerConnection();
    m_builtInActive = !url.isEmpty();
    m_builtInUrl = url;
    m_builtInHeaders = headers;
    syncServers();
}

// Reconciles m_servers with the desired server set: the builtin Qt Creator
// server (when available) first, then the user-configured servers in their
// stored order. Existing clients are kept (connectTo() re-handshakes only
// when the URL or headers changed); clients for removed servers are
// disconnected and deleted.
void McpBridge::syncServers()
{
    QVector<QPair<QString, QPair<QUrl, QStringList>>> desired;
    if (m_builtInActive)
        desired.append(
            {QString::fromUtf8(kBuiltInServerName), QPair{m_builtInUrl, m_builtInHeaders}});
    for (const Tools::McpServerConfig &config :
             Tools::McpServerConfig::fromJson(settings().mcpServersJson()))
        desired.append({config.name, {config.url, config.headers}});

    // Drop clients for servers that are gone.
    for (auto it = m_servers.begin(); it != m_servers.end();) {
        const bool wanted = std::any_of(desired.begin(),
                                        desired.end(),
                                        [&it](const auto &d) { return d.first == it->name; });
        if (!wanted) {
            it->client->disconnectFromServer();
            it->client->deleteLater();
            it = m_servers.erase(it);
        } else {
            ++it;
        }
    }

    // Create the remaining clients (if new) and (re)connect them.
    for (const auto &entry : desired) {
        Server *existing = nullptr;
        for (Server &server : m_servers)
            if (server.name == entry.first)
                existing = &server;

        if (!existing) {
            m_servers.append(Server{});
            existing = &m_servers.last();
            existing->name = entry.first;
            existing->client = new Tools::McpClient(this);
            connect(existing->client,
                    &Tools::McpClient::toolsChanged,
                    this,
                    &McpBridge::toolsChanged);
            connect(existing->client,
                    &Tools::McpClient::connectedChanged,
                    this,
                    &McpBridge::connectionChanged);
        }

        // connectTo() is a no-op when URL and headers are unchanged.
        existing->client->connectTo(entry.second.first, entry.second.second);
    }
}

} // namespace LlamaCpp

#include "mcptool.h"

#include "llamatr.h"
#include "mcpbridge.h"

#include <QJsonDocument>
#include <QRegularExpression>

namespace LlamaCpp::Tools {

McpTool::McpTool(const QString &name)
    : m_name(name)
{}

QString McpTool::toolDefinition() const
{
    const McpToolInfo info = McpBridge::instance().toolInfo(m_name);

    QJsonObject function;
    function["name"] = m_name;
    function["description"] = info.description.isEmpty()
                                  ? QStringLiteral("Tool provided by the Qt Creator MCP server.")
                                  : info.description;

    QJsonObject parameters = info.inputSchema;
    if (parameters.isEmpty()) {
        parameters["type"] = QStringLiteral("object");
        parameters["properties"] = QJsonObject();
    }
    function["parameters"] = parameters;

    QJsonObject root;
    root["type"] = QStringLiteral("function");
    root["function"] = function;

    return QString::fromUtf8(QJsonDocument(root).toJson(QJsonDocument::Indented));
}

QString McpTool::oneLineSummary(const QJsonObject &arguments) const
{
    // Show the first string argument to give the user an idea of what is
    // being done, e.g. "build_project ~/Projects/foo/CMakeLists.txt".
    const auto it = arguments.constBegin();
    if (it == arguments.constEnd())
        return m_name;

    QString value;
    if (it.value().isString())
        value = it.value().toString();
    else
        // non-string first argument - show the whole arguments object
        // (note: QJsonDocument::fromVariant() returns an empty document for
        // primitive values, so the variant route cannot be used here)
        value = QString::fromUtf8(QJsonDocument(arguments).toJson(QJsonDocument::Compact));

    if (value.size() > 80)
        value = value.left(77) + QStringLiteral("...");

    return m_name + QLatin1Char(' ') + value;
}

QString McpTool::streamingSummary(const QString &partialArguments) const
{
    // Mid-stream the arguments are a truncated JSON text – pick up the
    // first string value that has arrived so far; the closing quote is
    // optional since it has not arrived yet while streaming.
    static const QRegularExpression re(R"rx("([a-zA-Z_][a-zA-Z0-9_\-]*)"\s*:\s*"((?:[^"\\]|\\.)*)"?)rx");
    const QRegularExpressionMatch match = re.match(partialArguments);
    if (!match.hasMatch() || match.captured(2).isEmpty())
        return {};

    QString value = match.captured(2);
    value.replace(QStringLiteral("\\n"), QStringLiteral(" "));
    if (value.size() > 60)
        value = value.left(57) + QStringLiteral("...");

    return m_name + QLatin1Char(' ') + value;
}

QString McpTool::detailsMarkdown(const QJsonObject &arguments, const QString &result, bool ok) const
{
    Q_UNUSED(ok);
    QString md;
    if (!arguments.isEmpty()) {
        md += QStringLiteral("**Arguments**\n\n")
              + codeFence(QString::fromUtf8(QJsonDocument(arguments).toJson(QJsonDocument::Indented)),
                          QStringLiteral("json"));
    }
    if (!result.isEmpty()) {
        if (!md.isEmpty())
            md += QLatin1Char('\n');
        md += QLatin1Char('\n') + codeFence(result);
    }
    return md;
}

void McpTool::run(const QJsonObject &arguments,
                  std::function<void(const QString &output, bool ok)> done) const
{
    auto call = std::make_shared<CallState>();
    m_call = call;
    // Weak: the callback is owned by the client's pending call map, so a
    // strong reference would only keep the state alive for nothing.
    std::weak_ptr<CallState> weakCall = call;
    const McpBridge::ToolCallHandle handle = McpBridge::instance().callTool(
        m_name,
        arguments,
        [weakCall, done = std::move(done)](const QString &output, bool ok) {
            if (const auto state = weakCall.lock()) {
                if (state->finished)
                    return;
                state->finished = true;
            }
            done(output, ok);
        });
    // The callback may already have run synchronously (server unavailable),
    // in which case there is nothing left to abort.
    if (!call->finished)
        call->handle = handle;
}

void McpTool::abort()
{
    // Safe before run(), after the call finished, and more than once: the
    // client invokes the done callback at most once (cancelToolCall() is a
    // no-op for a finished call).
    if (!m_call || m_call->finished)
        return;
    // Copies: the done callback may destroy this tool.
    const McpBridge::ToolCallHandle handle = m_call->handle;
    McpBridge::cancelToolCall(handle,
                              Tr::tr("MCP tool \"%1\" was stopped by the user.").arg(m_name));
}

