QString SearchTool::toolDefinition() const
{
    return R"raw(
    {
        "type": "function",
        "function": {
            "name": "search",
            "description": "Searches file contents for a pattern using ripgrep. Returns matching lines as 'path:line: text' with paths relative to the searched directory, respecting .gitignore. Output is limited to the first 100 matches or 50 KB, whichever is hit first.",
            "parameters": {
                "type": "object",
                "properties": {
                    "pattern": { "type": "string", "description": "Search pattern (regular expression, or literal string when literal is true)." },
                    "path": { "type": "string", "description": "Directory or file to search, absolute or relative to the project directory. Defaults to the project directory." },
                    "glob": { "type": "string", "description": "Only search files matching this glob, e.g. '*.cpp'." },
                    "ignore_case": { "type": "boolean", "description": "Case-insensitive. Defaults to false." },
                    "literal": { "type": "boolean", "description": "Treat the pattern as a literal string. Defaults to false." },
                    "context": { "type": "integer", "description": "Lines to show before and after each match (0 to 20). Defaults to 0." },
                    "limit": { "type": "integer", "description": "Maximum number of matches (1 to 1000). Defaults to 100." }
                },
                "required": ["pattern"],
                "strict": true
            }
        }
    })raw";
}

QString SearchTool::streamingSummary(const QString &partialArgs) const
{
    const QString pattern = extractPartialString(partialArgs, QStringLiteral("pattern"));
    if (pattern.isEmpty())
        return {};
    return Tr::tr("search for %1").arg(codeSpan(pattern));
}

QString SearchTool::oneLineSummary(const QJsonObject &args) const
{
    const QString pattern = args.value("pattern").toString();
    if (pattern.isEmpty())
        return {};
    return Tr::tr("search for %1").arg(codeSpan(pattern));
}

QString SearchTool::detailsMarkdown(const QJsonObject &arguments, const QString &result, bool ok) const
{
    Q_UNUSED(ok);
    const QString pattern = arguments.value("pattern").toString();
    const QString glob = arguments.value("glob").toString();
    QString md = Tr::tr("Pattern: %1").arg(codeSpan(pattern));
    if (!glob.isEmpty())
        md += Tr::tr("  Glob: %1").arg(codeSpan(glob));
    const QString path = arguments.value("path").toString();
    if (!path.isEmpty())
        md += Tr::tr("  Path: %1").arg(codeSpan(path));
    md += QStringLiteral("\n\n") + codeFence(result);
    return md;
}

QString SearchTool::summaryPreview(const QJsonObject &arguments, const QString &result, bool ok) const
{
    Q_UNUSED(arguments);
    // The pattern header is already part of the one‑line summary; preview
    // the matches themselves, not the header (the default preview would
    // cut off right after the opening fence and render an empty block).
    return listPreview(result, ok);
}

void SearchTool::run(const QJsonObject &args,
                     std::function<void(const QString &, bool)> done) const
{
    const FilePath rgPath = Ripgrep::resolvedPath();
    if (rgPath.isEmpty()) {
        return done(Tr::tr("Error: ripgrep (rg) was not found. It can be downloaded from the "
                           "Llama.cpp Chat tools settings page, or installed manually from "
                           "https://github.com/BurntSushi/ripgrep, to use the search tool."),
                    false);
    }

    const QString pattern = args.value("pattern").toString();
    if (pattern.isEmpty()) {
        return done(Tr::tr("Error: the pattern must not be empty."), false);
    }

    const FilePath root = absoluteProjectPath(FilePath::fromUserInput(args.value("path").toString()));
    if (const QString error = sandboxAccessError(root, /*isWrite=*/false); !error.isEmpty())
        return done(error, false);
    const QString rootString = root.toUserOutput();
    if (!root.exists()) {
        return done(Tr::tr("Error: path does not exist: %1").arg(rootString), false);
    }
    const bool rootIsDir = QFileInfo(rootString).isDir();

    const int limit = qBound(1, args.value("limit").toInt(kDefaultLimit), kMaxLimit);
    const int context = qBound(0, args.value("context").toInt(0), kMaxContext);
    const bool sandboxed = sandboxEnabled(ProjectExplorer::ProjectManager::startupProject());

    const QStringList rgArgs = [&] {
        QStringList a;
        a << QStringLiteral("--json")
          << QStringLiteral("--line-number")
          << QStringLiteral("--color=never")
          << QStringLiteral("--hidden");
        if (args.value("ignore_case").toBool())
            a << QStringLiteral("--ignore-case");
        if (args.value("literal").toBool())
            a << QStringLiteral("--fixed-strings");
        const QString glob = args.value("glob").toString();
        if (!glob.isEmpty())
            a << QStringLiteral("--glob") << glob;
        // Hidden files are searched (e.g. .github workflows), but never the
        // .git directory itself. The negation must come last: ripgrep applies
        // the last matching glob, so a broad user glob would otherwise
        // re-include .git.
        a << QStringLiteral("--glob") << QStringLiteral("!.git");
        // Likewise never the credential locations inside the searched
        // directory (e.g. ~/.ssh when searching the home directory).
        if (sandboxed && rootIsDir) {
            for (const QString &secret : [REDACTED] {
                a << QStringLiteral("--glob") << QString(QStringLiteral("!") + secret)
                  << QStringLiteral("--glob")
                  << QString(QStringLiteral("!") + secret + QStringLiteral("/**"));
            }
        }
        if (context > 0)
            a << QStringLiteral("--context") << QString::number(context);
        a << QStringLiteral("--") << pattern << rootString;
        return a;
    }();

    auto *state = new SearchState;
    state->searchRoot = rootString;
    state->rootIsDir = rootIsDir;
    state->limit = limit;
    state->sandboxed = sandboxed;
    if (sandboxed)
        state->secretSpellings = secretPathSpellings();
    m_state = state;

    QProcess *process = new QProcess(state);
    state->process = process;
    process->setProcessChannelMode(QProcess::SeparateChannels);

    QTimer *timer = new QTimer(state);
    timer->setSingleShot(true);
    QObject::connect(timer,
                     &QTimer::timeout,
                     state,
                     [state] {
                         state->timedOut = true;
                         state->process->kill();
                     });

    QObject::connect(process,
                     &QProcess::readyReadStandardOutput,
                     state,
                     [state] {
                         state->pending += state->process->readAllStandardOutput();
                         int idx;
                         while ((idx = state->pending.indexOf('\n')) != -1) {
                             const QByteArray line = state->pending.left(idx).trimmed();
                             state->pending.remove(0, idx + 1);
                             if (line.isEmpty())
                                 continue;
                             handleRgEvent(state, line);
                             // Collect no more events once the limit is reached.
                             if (state->matchCount >= state->limit)
                                 break;
                         }
                         // Stop the search as soon as the limit is reached.
                         if (state->matchCount >= state->limit
                             && state->process->state() != QProcess::NotRunning) {
                             state->limitReached = true;
                             state->process->kill();
                         }
                     });

    QObject::connect(process,
                     &QProcess::readyReadStandardError,
                     state,
                     [state] { state->stderrText += QString::fromUtf8(state->process->readAllStandardError()); });

    // Reports the result exactly once: when ripgrep finished, or when it
    // failed to start (QProcess emits no finished() then). The tool itself
    // is kept alive by ChatManager until done() runs, so capturing this is
    // safe (and Tool is not a QObject, so it cannot be a context object).
    const auto finish = std::make_shared<std::function<void(int)>>(
        [this, state, done = std::move(done)](int exitCode) mutable {
            if (state->finished)
                return;
            state->finished = true;
            m_state = nullptr;
            state->stderrText += QString::fromUtf8(state->process->readAllStandardError());

            QString matches = state->outputLines.join(QLatin1Char('\n'));
            QStringList notes;
            bool ok = true;

            if (state->aborted) {
                ok = false;
                notes << Tr::tr("[Search was stopped by the user. The results are incomplete.]");
            } else if (state->timedOut && !state->limitReached) {
                ok = false;
                notes << Tr::tr("[Search timed out after %1 ms. The results are "
                                "incomplete; narrow the path or refine the pattern.]")
                             .arg(kTimeoutMs);
            } else if (state->processError == QProcess::FailedToStart) {
                ok = false;
                notes << Tr::tr("[Failed to start ripgrep: %1]")
                             .arg(state->errorString.isEmpty()
                                      ? Tr::tr("unknown error")
                                      : state->errorString);
            } else if (exitCode > 1 && !state->limitReached) {
                ok = false;
                notes << Tr::tr("[ripgrep failed (exit code %1): %2]")
                             .arg(exitCode)
                             .arg(state->stderrText.trimmed().isEmpty()
                                      ? Tr::tr("unknown error")
                                      : state->stderrText.trimmed());
            }

            if (state->limitReached)
                notes << Tr::tr("[%1 matches limit reached. Use limit=%2 for more results, "
                                "or refine the pattern.]")
                           .arg(state->limit)
                           .arg(state->limit * 2);
            if (state->linesTruncated)
                notes << Tr::tr("[Some lines truncated to %1 characters. Use read_file to "
                                "see full lines.]")
                           .arg(kMaxLineLength);

            QString result;
            if (matches.isEmpty()) {
                result = Tr::tr("No matches found.");
            } else {
                result = matches;
                QByteArray utf8 = matches.toUtf8();
                if (utf8.size() > kMaxOutputBytes) {
                    int pos = kMaxOutputBytes;
                    const int nl = utf8.lastIndexOf('\n', pos);
                    if (nl != -1)
                        pos = nl;
                    result = QString::fromUtf8(utf8.left(pos));
                    notes << Tr::tr("[Output truncated to %1 KB. Refine the pattern or "
                                    "reduce the context to see all matches.]")
                               .arg(kMaxOutputBytes / 1024);
                }
            }

            if (!notes.isEmpty())
                result += QLatin1Char('\n') + QLatin1Char('\n') + notes.join(QLatin1Char('\n'));

            state->deleteLater();
            done(result, ok);
        });

    QObject::connect(process,
                     &QProcess::errorOccurred,
                     state,
                     [state, finish](QProcess::ProcessError error) {
                         state->processError = error;
                         state->errorString = state->process->errorString();
                         if (error == QProcess::FailedToStart)
                             (*finish)(-1);
                     });

    // No context object: the connection dies with the process.
    QObject::connect(process,
                     qOverload<int, QProcess::ExitStatus>(&QProcess::finished),
                     [finish](int exitCode, QProcess::ExitStatus) { (*finish)(exitCode); });

    timer->start(kTimeoutMs);
    process->start(rgPath.toUserOutput(), rgArgs);
}

void SearchTool::abort()
{
    SearchState *state = m_state;
    m_state = nullptr;
    if (state && state->process && state->process->state() != QProcess::NotRunning) {
        state->aborted = true;
        state->process->kill();
    }
}

